"""Local JobGuts demonstration UI using only stored rule artifacts."""
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse
import json
from src.retrieval import RuleRepository
from src.normalization.dictionary import TechnologyDictionary

ROOT=Path(__file__).resolve().parents[2]
HTML='''<!doctype html><html lang="ko"><meta charset="utf-8"><title>JobGuts</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#0c0c0c;color:#f5f5f5}.wrap{max-width:1120px;margin:auto;padding:32px}.nav{display:flex;justify-content:space-between;align-items:center;padding-bottom:18px;border-bottom:1px solid #303030}.brand{font-weight:800;font-size:22px}.tag{color:#bdbdbd;letter-spacing:.04em}.hero{padding:72px 0 30px;display:grid;grid-template-columns:1.2fr .8fr;gap:28px}.hero h1{font-size:54px;line-height:1.05;margin:0 0 18px}.hero p{color:#c6c6c6;font-size:18px;line-height:1.6}.panel{background:#171717;border:1px solid #3d3d3d;border-radius:18px;padding:22px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{background:#101010;padding:16px;border-radius:12px}.num{font-size:26px;font-weight:bold;color:#fff}.search{display:flex;gap:10px;margin-top:24px}.search input{flex:1;padding:15px;border:1px solid #555;border-radius:10px;font-size:16px;background:#f5f5f5}.search button{background:#f2f2f2;color:#111;border:0;border-radius:10px;padding:0 20px;font-weight:bold}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.card{background:#171717;border:1px solid #3d3d3d;border-radius:16px;padding:20px}.muted{color:#b8b8b8}.rule{padding:14px 0;border-bottom:1px solid #363636}.pill{display:inline-block;background:#343434;color:#f1f1f1;padding:4px 8px;border-radius:99px;font-size:12px;margin-right:5px}.metric{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px}.metric b{display:block}.evidence{font-size:14px;padding:10px;background:#101010;border-radius:8px;margin-top:8px}@media(max-width:700px){.hero,.grid{grid-template-columns:1fr}.hero h1{font-size:40px}.stats{grid-template-columns:1fr}}
</style><body><main class="wrap"><nav class="nav"><div class="brand">JobGuts <span class="tag">/ skill intelligence</span></div><div class="tag">Apriori · Evidence-first</div></nav><section class="hero"><div><div class="tag">KOREAN IT JOB MARKET ANALYSIS</div><h1>다음에 검토할<br>기술을 찾습니다.</h1><p>보유 기술을 입력하면 실제 채용공고의 기술 조합을 기반으로 연관 기술과 근거 공고를 보여줍니다.</p><div class="search"><input id="skill" value="TensorFlow" aria-label="보유 기술"><button onclick="go()">추천 보기</button></div></div><div class="panel"><div class="tag">CURRENT DATASET</div><h2>40,348 postings</h2><div class="stats"><div class="stat"><div class="num">17,796</div><small>transactions</small></div><div class="stat"><div class="num">694</div><small>rules</small></div><div class="stat"><div class="num">8</div><small>tests passed</small></div></div></div></section><section class="grid"><div class="card"><div class="tag">RECOMMENDATIONS</div><h2 id="title">기술을 입력하세요</h2><div id="rules" class="muted">TensorFlow로 데모 결과를 불러올 수 있습니다.</div></div><div class="card"><div class="tag">EVIDENCE POSTINGS</div><h2>근거 공고</h2><div id="evidence" class="muted">추천 기술과 함께 나타난 실제 공고를 표시합니다.</div></div></section><section class="card" style="margin-top:20px"><div class="tag">HOW IT WORKS</div><h2>입력 → 정규화 → 규칙 조회 → 근거 확인</h2><p class="muted">support는 조합의 비율, confidence는 조건부 비율, interest는 결과 기술의 기본 출현 비율을 제외한 연관성입니다. 현재 화면은 저장된 분석 결과를 조회하며, 규칙을 다시 계산하지 않습니다.</p></section></main><script>async function go(){let s=document.getElementById('skill').value;let d=await fetch('/api/recommend?skills='+encodeURIComponent(s)).then(x=>x.json());document.getElementById('title').textContent=d.status==='ok'?'추천 결과':'추천 결과 없음';let r=document.getElementById('rules'),e=document.getElementById('evidence');if(!d.recommendations?.length){r.textContent=d.next_action||d.status;e.textContent='근거 공고가 없습니다.';return}r.innerHTML=d.recommendations.map(x=>`<div class="rule"><span class="pill">${x.antecedent[0]}</span> → <span class="pill">${x.consequent[0]}</span><div class="metric"><div><small>support</small><b>${x.support.toFixed(4)}</b></div><div><small>confidence</small><b>${x.confidence.toFixed(4)}</b></div><div><small>interest</small><b>${x.interest.toFixed(4)}</b></div></div></div>`).join('');e.innerHTML=d.evidence_postings.map(x=>`<div class="evidence"><b>${x.title||'제목 없음'}</b><br><span class="muted">${x.source} · ${x.job_id}</span></div>`).join('')}go();</script></body></html>'''
class App(BaseHTTPRequestHandler):
 def do_GET(self):
  u=urlparse(self.path)
  if u.path=='/': self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.end_headers();self.wfile.write(HTML.encode());return
  if u.path=='/api/recommend':
   q=parse_qs(u.query); raw=q.get('skills',[''])[0]; d=TechnologyDictionary.from_json(ROOT/'configs/tech_dictionary.json'); skills=[d.canonicalize(x.strip()) or x.strip() for x in raw.split(',') if x.strip()]; data=RuleRepository(ROOT/'artifacts/week12_top_rules.json',ROOT/'data/processed/postings_normalized.jsonl').recommend(skills); self.send_response(200);self.send_header('Content-Type','application/json; charset=utf-8');self.end_headers();self.wfile.write(json.dumps(data,ensure_ascii=False).encode());return
  self.send_error(404)
if __name__=='__main__':
 print('JobGuts UI: http://127.0.0.1:8765'); ThreadingHTTPServer(('127.0.0.1',8765),App).serve_forever()
